func (e *Engine) Run(ctx context.Context) error {
	if err := e.Boot(ctx); err != nil {
		return err
	}
	// A TERM'd Boot can successfully finish its local baseline. Do not start
	// a new Step audit/budget before Close after that completed stop request.
	if err := ctx.Err(); err != nil {
		return err
	}
	interval := e.stepInterval()
	// SIGHUP reloads resolver credentials between steps. It does not stop
	// the process. SIGINT and SIGTERM still cancel ctx.
	hup := make(chan os.Signal, 1)
	signal.Notify(hup, syscall.SIGHUP)
	defer signal.Stop(hup)
	for {
		started := e.clock.Mono()
		if err := e.Step(ctx); err != nil && ctx.Err() != nil {
			return ctx.Err()
		}
		if signaled(hup) {
			e.reloadResolvers()
		}
		timer := time.NewTimer(min(e.nextStepDelay(interval), e.remainingStepDelay(started, interval)))
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-hup:
			timer.Stop()
			e.reloadResolvers()
		case <-timer.C:
		}
	}
}

// nextStepDelay wakes at a grant-less renewal slot even when the preceding
// control work took time or the configured poll is longer than the slot.
// Failed requests and replayed expired leases retry at the control cadence,
// rather than spinning on an already elapsed deadline. Retry-After wins.
func (e *Engine) nextStepDelay(interval time.Duration) time.Duration {

// Re-decide on this tick after a planned deadline withdrawal. Surviving
// siblings must not wait another poll merely because one device expired.
e.expireServing(ctx)
// Do not replace persisted desired provenance or bindings while a restart
// delta is pending. A held sample retries with forwarding still withdrawn.
if e.retainedPending {
	e.ensureUsage(ctx)
	if !e.settleRetainedUsage(ctx) {
		e.decision = Decide(e.input())
		return nil
	}
}
// Check the retained model before Apply can overwrite evidence of drift.
// A valid same-generation mismatch is repaired immediately after retaining
// the rejected read. Other failures still withdraw before a later Apply.
if !e.verifyCurrentServing(ctx) {
	_ = e.observe(ctx)
	_ = e.flush(ctx)
	return nil
}

e.ensureUsage(ctx)
if e.uploader != nil && e.uploader.NeedsRestore() {
	e.restoreUsage(ctx)
}
e.readMeter(ctx)
if pending, err := e.store.Pending(ctx); err == nil {
	e.outboxFull = len(pending) >= 32
}
e.evaluate(ctx)
if err := e.enforce(ctx, e.decision); err != nil && ctx.Err() != nil {

lock, err := nodelock.Acquire(ctx, e.cfg.LockPath, 3, 50*time.Millisecond)
if errors.Is(err, nodelock.ErrBusy) {
	e.decision.Errors = append(e.decision.Errors, api.NodeError{
		Code: api.ErrorCodeUPDATEBUSY, Message: "UPDATE_BUSY",
		ObservedAt: e.clock.Wall().UTC(), Stage: "apply",
	})
	if !e.serving {
		e.decision.Reasons = append(e.decision.Reasons, api.ForwardingBlockReasonUpdateInProgress)
		e.decision.Serve = false
	}
	return nil
}
if err != nil {
	return err
}
defer lock.Release()
// The updater may have published its block since this step's decision.
// Re-read under the node lock before invalidating evidence or admitting.
e.latch()
if e.latchBlocked {
	e.decision = Decide(e.input())
	e.withdraw(ctx)
	return nil
}
e.planeLocked = true
defer func() { e.planeLocked = false }()
if !closedRecovery && e.canRetainServing(ctx, d) {
	// Same installed model, but fresh live evidence is still mandatory.
	// Failures take the ordinary reject/quarantine/withdraw path; no
	// cached evidence or elapsed control timeout authorizes a skip.
	if e.verifyServingModel(ctx, *e.appliedModel, e.appliedAssignments) &&
		!e.expireServing(ctx) && e.checkMemberPath(ctx, *e.appliedModel) {
		e.beat()
	}
	return nil

if !closedRecovery {
	e.resumeSampling()
	e.switchEpoch(ctx)
}

func (e *Engine) withdraw(ctx context.Context) {
	e.handoff(ctx)
	_ = e.baseline(ctx)
	e.serving = false
	e.policyExpires = 0
}

func (e *Engine) beat() {
	mono := e.clock.Mono()
	if mono <= 0 || e.bootID == uuid.Nil {
		return
	}
	reason := "-"
	if e.serving {
		reason = "serving"
	} else if len(e.decision.Reasons) > 0 {
		reason = string(e.decision.Reasons[0])
	}

		e.decision = Decide(e.input())
		e.lastObs = time.Time{}
		return false
	}
	if e.expireServing(ctx) {
		return false
	}
	if e.appliedModel == nil {
		e.rejectServing(ctx, enforce.Model{}, enforce.ServingEvidence{}, errors.New("missing applied model"))
		return false
	}
	if !e.verifyServingModel(ctx, *e.appliedModel, e.appliedAssignments) {
		return false
	}
	// The live read may straddle expiry. It proves rules, not a renewed lease.
	if e.expireServing(ctx) {
		return false
	}
	// Publish the verified state before synchronous control work can stall.
	e.beat()
	return true
}

func (e *Engine) expireServing(ctx context.Context) bool {
	if !e.serving || (e.policyExpires > 0 && e.clock.Mono() < e.policyExpires) {
		return false
	}
	cleanup, cancel := context.WithTimeout(localContext(ctx), 5*time.Second)
	defer cancel()
	e.withdraw(cleanup)
	e.decision = Decide(e.input())
	e.lastObs = time.Time{}
	return true
}

