func sameEnforcement(applied, next enforce.Model, assignments map[uuid.UUID]uint16) bool {
	if applied.NowMono <= 0 || next.NowMono < applied.NowMono ||
		!applied.Now.Add(next.NowMono-applied.NowMono).Equal(next.Now) {
		return false
	}
	applied.Now, next.Now = time.Time{}, time.Time{}
	applied.NowMono, next.NowMono = 0, 0
	applied.QoS.Assignments = assignments
	applied.Revoke = nil
	return reflect.DeepEqual(applied, next)
}

// Called only under the node lock after rereading the updater latch. An audit
// model survives withdrawal/reboot, so its presence alone permits nothing.
func (e *Engine) canRetainServing(ctx context.Context, d Decision) bool {
	if !e.serving || !d.Serve || !e.baselineOK || !e.storageOK || e.applyError != nil ||
		e.failedCandidate != nil || e.appliedModel == nil || e.appliedSnapshot == nil ||
		e.leaseBoot != e.bootID || e.appliedGen != d.Model.Generation || e.policyExpires != d.PolicyExpires ||
		e.policyExpires <= e.clock.Mono() || e.latchBlocked || e.repairing ||
		len(e.pendingRevoke) != 0 || e.conntrackAttempts != 0 || e.conntrackBlocked ||
		len(planRevokes(nil, e.addresses, d.Model.Bindings)) != 0 ||
		e.memberPath == nil || e.memberPathPending || e.quarantinePending || e.probeCleanup != nil ||
		e.retainedPending || e.usagePersist || e.usageAdopting || e.epochClosed || e.finalDone ||
		e.finalBarrierID != "" || e.shutUsage || !e.sampleOn || !e.expectServing.Load() ||
		e.meter == nil || e.usage == nil || !sameUsageBindings(e.meterBindings(), d.Model.Bindings) ||
		(e.kernel != nil && e.kernel.nudgePending()) ||
		!sameEnforcement(*e.appliedModel, d.Model, e.appliedAssignments) {
		return false
	}
	// A reset may have changed the epoch since the last Apply. Keep its intent
	// and synchronous switch path current instead of relying on a future change.
	h, err := e.usage.Head(ctx)
	if err != nil {
		return false
	}
	intent := e.restartIntent
	return intent != nil && h.OpenEpoch != uuid.Nil && h.BootID == e.bootID.String() &&
		intent.Boot == e.bootID && intent.Epoch == h.OpenEpoch &&
		uint64(intent.Generation) == d.Model.Generation && sameUsageBindings(intent.bindings(), d.Model.Bindings)
}

// switchEpoch opens one meter epoch through Meter.Sample when the counter
// values alone would not. The one-packet nudge is consumed by whichever
// sample reads first.
func (e *Engine) switchEpoch(ctx context.Context) {
	if e.kernel == nil || e.meter == nil || !e.kernel.nudgePending() {
		return
	}
	err := e.meter.Sample(ctx)
	if errors.Is(err, meter.ErrBusy) {
		time.Sleep(20 * time.Millisecond)
		err = e.meter.Sample(ctx)
	}
	if err == nil || ctx.Err() != nil {
		return
	}
	if errors.Is(err, meter.ErrBusy) {
		return
	}
	if !e.kernel.nudgePending() {
		e.kernel.rearm()
	}
	if !errors.Is(err, meter.ErrHold) && !errors.Is(err, meter.ErrPaused) {
		e.log.Warn("meter epoch", "err", err.Error())
	}
}

func verifyAllowedPresence(raw []byte, m enforce.Model, at time.Duration) error {
	rs, err := enforce.ParseRuleset(raw)
	if err != nil {
		return err
	}
	now := m.Now
	if m.NowMono > 0 {
		if at < m.NowMono {
			return &enforce.CheckError{Reason: enforce.ReasonIsolation, Detail: "monotonic presence read precedes model"}
		}
		now = now.Add(at - m.NowMono)
	}
	present := map[netip.Addr]bool{}
	for _, el := range rs.Elements["allowed_v4"] {
		present[el.Addr] = true
	}
	for _, b := range m.Bindings {
		if !b.ValidFrom.IsZero() && now.Before(b.ValidFrom) {
			continue
		}
		for _, l := range m.Leases {
			if l.MemberID != b.MemberID {
				continue
			}
			end, ok := enforce.ForwardingDeadline(l)
			if !ok {
				continue
			} // the full serving verifier rejects invalid leases
			if !b.ValidUntil.IsZero() && b.ValidUntil.Before(end) {
				end = b.ValidUntil
			}
			remaining := end.Sub(now)
			if l.DeadlineMono != nil {
				remaining = min(remaining, *l.DeadlineMono-at)
			}
			if l.TimeoutCeilSeconds > 0 && m.NowMono > 0 && l.TimeoutCeilSeconds <= uint64((1<<63-1)/int64(time.Second)) {
				remaining = min(remaining, time.Duration(l.TimeoutCeilSeconds)*time.Second-(at-m.NowMono))
			}
			// A legitimate D-104 element can disappear this much before D. Never
			// call the existing safety reserve a drift or extend its signed window.
			if remaining <= enforce.DeadlineInstallBound+enforce.DeadlineGranularity {
				continue
			}
			for _, prefix := range b.AllowedV4 {
				if !present[prefix.Addr()] {
					return &enforce.CheckError{Reason: enforce.ReasonIsolation, Detail: "allowed_v4 is missing a live binding"}
				}
			}
		}
	}

func (e *Engine) recordUsageIntent(ctx context.Context, model enforce.Model) error {
	if e.usage == nil || e.meter == nil {
		return fmt.Errorf("usage: no owned meter for admission")
	}
	h, err := e.usage.Head(ctx)
	if err != nil {
		return err
	}
	if h.OpenEpoch == uuid.Nil || h.BootID != e.bootID.String() {
		return fmt.Errorf("usage: no current epoch for admission")
	}
	if old := e.restartIntent; old != nil && old.Boot == e.bootID && old.Epoch == h.OpenEpoch && uint64(old.Generation) == model.Generation && sameUsageBindings(old.bindings(), model.Bindings) {
		return nil // a same-generation renewal needs no second durable intent
	}
	intent := usageIntent{Boot: e.bootID, Epoch: h.OpenEpoch, Generation: decstr.U64(model.Generation)}
	for _, b := range model.Bindings {
		intent.Bindings = append(intent.Bindings, usageIdentity{Device: b.DeviceID, Member: b.MemberID, Revision: decstr.U64(b.BindingRevision)})
	}
	raw, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	if err := e.store.SetMeta(ctx, usageIntentKey, string(raw)); err != nil {
		return err
	}
	e.restartIntent = &intent
	return nil
}

func (e *Engine) captureRestartBindings(ctx context.Context) {
	e.restartBindings, e.restartIntent = nil, nil
	// A failed nft read is not evidence that the durable intent disappeared.
	// The ledger checks its interval below; adoption still verifies live rules.
	if raw, exists, err := e.store.Meta(ctx, usageIntentKey); err == nil && exists {
		var intent usageIntent
		if json.Unmarshal([]byte(raw), &intent) == nil && intent.Boot == e.bootID && intent.Epoch != uuid.Nil && intent.Generation != 0 {
			e.restartIntent = &intent
		}
	}
	reader, ok := e.plane.(interface {
		RestartGeneration(context.Context) (uint64, error)
	})
	if !ok {
		return
	}
	readCtx, cancel := context.WithTimeout(ctx, e.servingReadTimeout())
	defer cancel()
	gen, err := reader.RestartGeneration(readCtx)
	if err != nil || readCtx.Err() != nil {
		return
	}
	retained, desired := e.appliedModel, e.restartDesired
	if p := e.restartIntent; p != nil && gen != 0 && gen != uint64(p.Generation) &&
		!(retained != nil && gen == retained.Generation && sameUsageBindings(retained.Bindings, p.bindings())) {
		e.restartIntent = nil // a contradictory live marker defeats the intent
	}

func (e *Engine) restartHeadBindings(ctx context.Context, st *usagestore.Store, h usagestore.Head) ([]enforce.Binding, error) {
	if h.OpenEpoch == uuid.Nil || h.BootID != e.bootID.String() {
		return nil, nil
	}
	if p := e.restartIntent; p != nil {
		if p.Epoch == h.OpenEpoch {
			return p.bindings(), nil
		}
		continuous, err := st.SameCountingInterval(ctx, p.Epoch, h.OpenEpoch, e.bootID.String())
		if err != nil {
			return nil, err
		}
		if continuous {
			return p.bindings(), nil
		}
	}

	e.retainedPending = false
	e.epochClosed = true
	e.finalDone = true
	e.setMeterBindings(nil)
	e.readMeter(ctx)
	return true
}

// readMeter copies the meter's health onto the forwarding gate.
// Store caps win inside meter.Health, so a full outbox is not reported
// as METER_PATH_INVALID.
func (e *Engine) readMeter(ctx context.Context) {
	defer func() {
		if e.retainedPending {
			e.usagePersist = true
		}
	}()
	if e.meter == nil {
		return
	}

persist, path, disk, outbox := e.usagePersist, e.meterFailed, e.usageDisk, e.usageOutbox
defer func() {
	e.usagePersist = e.usagePersist || persist
	e.meterFailed = e.meterFailed || path
	e.usageDisk = e.usageDisk || disk
	e.usageOutbox = e.usageOutbox || outbox
}()
id, blocked := meterBarrierIdentity(e.cfg.JournalDir)
e.latchBlocked = blocked
// The pending latch precedes every fallible withdrawal operation, even
// checkpoint removal. A later successful baseline retry must not allow
// Apply to overtake the outgoing interval (r23 H-3/M-1).
complete := e.finalDone && e.finalBarrierID == id && !e.retainedPending
if !complete && e.meter != nil {
	e.finalDone = false
	e.retainedPending = true
	e.serving = false
	e.policyExpires = 0
	e.decision.Serve = false
	if err := e.baseline(ctx); err != nil {
		return
	}
}
if id == "" {
	if err := e.invalidateMeterCheckpoint(); err != nil {
		e.usagePersist = true
		e.serving = false
		e.policyExpires = 0
		// Even a completed/no-meter hand-off must withdraw on a new
		// persistence failure. Do not let ledger health clear this error.
		if complete || e.meter == nil {
			_ = e.baseline(ctx)
		}
		return
	}
}
if e.meter == nil || complete {
	return
}
// FinalSample pauses internally. If it fails, the same settlement gate
// used at restart prevents refresh or Apply until the outgoing bytes commit.
if !e.settleRetainedUsage(ctx) {
	return
}
// Accounting is settled; the updater barrier is not acknowledged until
// its identity has been rechecked and its checkpoint has been published.
e.finalDone = false
cp, err := e.usage.ClosedCheckpoint(ctx)
if err != nil {
	e.usagePersist = true
	return
}
current, stillBlocked := meterBarrierIdentity(e.cfg.JournalDir)
if current != id || stillBlocked != blocked {
	// Withdrawal/replacement while closing is not acknowledgement of
	// either identity. The next pass performs a fresh barrier.
	if err := e.invalidateMeterCheckpoint(); err != nil {
		e.usagePersist = true
	}
	return
}
if id != "" {
	cp.BarrierID = id
	raw, err := e.meterCheckpointBytes(cp)
	if err == nil {
		err = writeAtomic(e.cfg.MeterCheckpoint, raw, 0o600)
	}
	if err != nil {
		e.usagePersist = true
		return
	}
}
e.finalDone = true

func memberTimeout(binding Binding, lease MemberLease, m Model) (time.Duration, bool) {
	deadline, ok := ForwardingDeadline(lease)
	if !ok || m.Now.IsZero() || (!binding.ValidFrom.IsZero() && m.Now.Before(binding.ValidFrom)) {
		return 0, false
	}
	if !binding.ValidUntil.IsZero() && binding.ValidUntil.Before(deadline) {
		deadline = binding.ValidUntil
	}
	remaining := deadline.Sub(m.Now)
	if remaining <= 0 {
		return 0, false
	}
	if lease.TimeoutCeilSeconds > 0 && lease.TimeoutCeilSeconds <= uint64((1<<63-1)/int64(time.Second)) {
		remaining = min(remaining, time.Duration(lease.TimeoutCeilSeconds)*time.Second)
	}
	if lease.DeadlineMono != nil {
		if m.NowMono <= 0 || *lease.DeadlineMono <= m.NowMono {
			return 0, false
		}
		remaining = min(remaining, *lease.DeadlineMono-m.NowMono)
	}
	if remaining <= m.timeoutReserve {
		return 0, false
	}
	remaining = (remaining - m.timeoutReserve).Truncate(DeadlineGranularity)
	return remaining, remaining >= DeadlineGranularity
}

// dns_service_v1, not forward_admission_v1.
for _, d := range devices {
	if !d.TimeoutOK() {
		continue
	}
	prio := fmt.Sprintf("0x%08x", ClassID(d.Minor))
	dnsUp := usageCounter(dirDNSUpload, d.Binding.DeviceID)
	for _, addr := range d.Addrs {
		rule(&b, "forward", fmt.Sprintf("iifname %q oifname %q ip saddr %s ip daddr @resolver_v4 tcp dport 53 counter name %q meta priority set %s accept", in, up, addr, dnsUp, prio))
		rule(&b, "forward", fmt.Sprintf("iifname %q oifname %q ip saddr %s ip daddr @resolver_v4 udp dport 53 counter name %q meta priority set %s accept", in, up, addr, dnsUp, prio))
	}
}
// Probe DNS is the same hole as member DNS: the resolver prefix is inside
// the deny list, and only dport 53 is accepted. The source element timeout
// closes the hole (§13.9).
if m.Probe != nil && m.Probe.ResolverDNS {
	writeProbeDNS(&b, in, up)
}
rule(&b, "forward", fmt.Sprintf("iifname %q oifname %q ip daddr @resolver_v4 counter name %q drop", in, up, counterBadDNS))
rule(&b, "forward", fmt.Sprintf("iifname %q oifname %q ip daddr @denied_v4 counter name %q drop", in, up, counterDenied))
rule(&b, "forward", fmt.Sprintf("iifname %q oifname %q ip daddr @host_v4 counter name %q drop", in, up, counterHost))
// General probe accepts sit behind the deny and host drops, and before
// any member accept. A tuple that is not in the set falls through.
if m.Probe != nil && len(m.Probe.Destinations) > 0 {
	writeProbeTuple(&b, in, up)
}

for _, d := range devices {
	if !d.TimeoutOK() {
		continue
	}
	prio := fmt.Sprintf("0x%08x", ClassID(d.Minor))
	upCounter := usageCounter(dirUpload, d.Binding.DeviceID)
	for _, addr := range d.Addrs {
		rule(&b, "forward", fmt.Sprintf("iifname %q oifname %q ip saddr %s counter name %q meta priority set %s accept", in, up, addr, upCounter, prio))
	}
}

func (s cachedStateSigner) Sign(ctx context.Context, purpose envelope.Purpose, signed any) (envelope.Envelope, error) {
	if desired, ok := signed.(api.DesiredState); ok && purpose == envelope.PurposeDesiredState && s.cached != nil {
		previous := s.cached.Envelope.Signed
		// CompileTx always proposes max(desired, applied, stored)+1, even for
		// unchanged content. Only its ordinary one-step proposal can be elided;
		// a different generation fence must reach the signer (D-099). Runtime
		// also excludes outstanding restore holds from cache eligibility.
		if desired.ConfigGeneration != previous.ConfigGeneration &&
			(desired.ConfigGeneration == 0 || desired.ConfigGeneration-1 != previous.ConfigGeneration) {
			return s.signer.Sign(ctx, purpose, signed)
		}
		// CompileTx has read all member eligibility, FUP and binding evidence but
